package sa.gba.academy.integrations;

import java.io.IOException;
import java.io.InputStream;
import org.springframework.core.io.Resource;

/** PORT: where uploaded bytes live (local disk now; S3 / Azure Blob / GCS later). Keys are generated by the API, never by users. */
public interface FileStorage {
    /** Store the stream under `key`; returns the number of bytes written. */
    long save(String key, InputStream in) throws IOException;

    /** Open a stored file for streaming (supports HTTP range requests, so videos can seek). */
    Resource open(String key);

    void delete(String key);
}
